    try:
        _winapi.get_handle_flags(number)
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    # GetFileType returns both the type and (implicitly) an error code.
    file_type, error = _winapi.get_file_type(number)

    if file_type == _winapi.FILE_TYPE_DISK:
        return "file"
    elif file_type == _winapi.FILE_TYPE_PIPE:
        return "pipe"
    elif file_type == _winapi.FILE_TYPE_CHAR:
        # Character device: might be a console or the NUL device.
        if _winapi.is_console_handle(number):
            return "console"
        return "file"  # NUL and other character devices
    elif file_type == _winapi.FILE_TYPE_UNKNOWN:
        # UNKNOWN can mean either an unrecognized type or an error.
        if error != _winapi.ERROR_SUCCESS:
            raise WSpawnError(
                "could not determine type of handle %r" % (handle,),
                kind="os",
                handle=handle,
            )
        return "unknown"
    else:
        # Some other type; report as unknown.
        return "unknown"

