from . import _winapi
from .errors import WSpawnError


def set_inheritable(handle, enabled=True):
    """Mark ``handle`` as transferable to child processes, or stop it being so.

    On Windows, this calls ``SetHandleInformation`` to change the
    ``HANDLE_FLAG_INHERIT`` bit, and confirms that the change actually took
    effect by reading the flag back with ``GetHandleInformation``.  If the
    object does not support changing the inheritable flag, raises
    :class:`WSpawnError` with ``kind="unsupported"``.
    """
    if not _winapi.is_windows():
        raise WSpawnError("set_inheritable is only available on Windows", kind="unsupported")

    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )

    # Set the flag.
    try:
        _winapi.set_handle_flags(
            number,
            _winapi.HANDLE_FLAG_INHERIT,
            _winapi.HANDLE_FLAG_INHERIT if enabled else 0,
        )
    except OSError as exc:
        error_code = _winapi.last_error()
        # ERROR_INVALID_PARAMETER often means the object does not support
        # the flag being changed.
        if error_code == _winapi.ERROR_INVALID_PARAMETER:
            raise WSpawnError(
                "handle %r does not support changing the inheritable flag" % (handle,),
                kind="unsupported",
                handle=handle,
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    # Read the flag back to confirm the change stuck.
    try:
        flags = _winapi.get_handle_flags(number)
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    actual = bool(flags & _winapi.HANDLE_FLAG_INHERIT)
    if actual != bool(enabled):
        raise WSpawnError(
            "handle %r did not accept the inheritable flag change" % (handle,),
            kind="unsupported",
            handle=handle,
        )


