    """Return ``True`` when ``handle`` is currently transferable."""
    if not _winapi.is_windows():
        raise WSpawnError("is_inheritable is only available on Windows", kind="unsupported")

    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )

    try:
        flags = _winapi.get_handle_flags(number)
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    return bool(flags & _winapi.HANDLE_FLAG_INHERIT)


def inheritable_handles():
    """Return every object in this process that is currently transferable.

    On Windows, this sweeps candidate handle values using
    ``GetHandleInformation`` and collects those with ``HANDLE_FLAG_INHERIT``
    set.  The sweep is bounded by ``GetProcessHandleCount`` so it does not
    have to test the full address space.
    """
    if not _winapi.is_windows():
        return []

    # Get a hint for how many handles to expect.
    try:
        expected_count = _winapi.process_handle_count()
    except OSError:
        expected_count = 256

    # Scan candidate handle values (multiples of 4 on Windows).
    found = []
    checked = 0
    max_handle = 0x10000
    for candidate in range(4, max_handle, 4):
        flags = _winapi.try_handle_flags(candidate)
        if flags is not None:
            checked += 1
            if flags & _winapi.HANDLE_FLAG_INHERIT:
                found.append(candidate)
            # Stop early if we have seen more handles than the process claims
            # to have; no need to scan the entire address space.
            if checked >= expected_count * 2:
                break

    return found

