import os
import subprocess

from . import _create, _winapi
from .errors import WSpawnError


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, process_handle, pid, inherit):
        self._handle = process_handle
        self.inherit = tuple(inherit)
        self.pid = pid
        self.returncode = None

    def wait(self, timeout=None):
        """Wait for the process to exit and return its exit code."""
        if self.returncode is not None:
            return self.returncode

        if timeout is None:
            timeout_ms = _create.INFINITE
        else:
            timeout_ms = int(timeout * 1000)

        exited = _create.wait_process(self._handle, timeout_ms)
        if not exited:
            raise subprocess.TimeoutExpired(cmd=None, timeout=timeout)

        self.returncode = _create.exit_code(self._handle)
        return self.returncode

    def poll(self):
        """Check if the process has exited and return its exit code if so."""
        if self.returncode is not None:
            return self.returncode

        # Use a zero timeout to check without blocking.
        exited = _create.wait_process(self._handle, 0)
        if exited:
            self.returncode = _create.exit_code(self._handle)
        return self.returncode

    def terminate(self):
        """Terminate the process."""
        _create.terminate_process(self._handle, 1)

    def close(self):
        """Release the process handle."""
        if self._handle:
            _winapi.close_handle(self._handle)
            self._handle = None

    def __del__(self):
        self.close()


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError(
            "argv must be a sequence of arguments, not a single string", kind="badarg"
        )
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError(
            "argv must be an iterable of paths: %s" % exc, kind="badarg"
        ) from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError(
            "inherit must be a sequence of handles, not a single handle", kind="badarg"
        )
    try:
        return tuple(int(item) for item in inherit)
    except (TypeError, ValueError) as exc:
        raise WSpawnError(
            "inherit must contain integer handles: %s" % exc, kind="badarg"
        ) from exc


def _resolve_std_handle(value, default_null=False):
    """Convert a standard stream argument into a Windows handle value.

    *value* can be:
    - ``None``: use null device if *default_null* is True, else 0 (disconnected)
    - ``subprocess.DEVNULL``: open null device
    - an integer: treat as a raw handle value
    - a file-like object: call ``fileno()`` and resolve to a handle

    Returns the handle value, or 0 for a disconnected stream.
    """
    if value is None:
        if default_null:
            return _winapi.open_null_device(read=True, write=True, inheritable=True)
        return 0

    if value == subprocess.DEVNULL:
        # Open the null device as an inheritable handle.
        return _winapi.open_null_device(read=True, write=True, inheritable=True)

    if isinstance(value, int):
        # Sentinel values like PIPE (-1) and STDOUT (-2) are not supported.
        if value < 0:
            raise WSpawnError(
                "wspawn does not support subprocess.PIPE or subprocess.STDOUT", kind="unsupported"
            )
        # Treat it as a raw handle.
        return value

    # Try to extract a file descriptor and convert to a handle.
    try:
        fd = value.fileno()
    except (AttributeError, OSError) as exc:
        raise WSpawnError(
            "could not get a file descriptor from %r: %s" % (value, exc), kind="badarg"
        ) from exc

    # Convert the file descriptor to a Windows handle.
    try:
        import msvcrt
        handle = msvcrt.get_osfhandle(fd)
    except (ImportError, OSError) as exc:
        raise WSpawnError(
            "could not convert file descriptor %r to a handle: %s" % (fd, exc),
            kind="os",
        ) from exc

    return handle


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    Returns a :class:`SpawnedProcess`.

    On Windows, this uses ``CreateProcessW`` with
    ``PROC_THREAD_ATTRIBUTE_HANDLE_LIST`` to ensure that the child can access
    only the handles explicitly listed in *inherit*, plus the standard streams
    if specified.
    """
    if not _winapi.is_windows():
        raise WSpawnError("spawn is only available on Windows", kind="unsupported")

    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    # Build the command line string.
    command_line = _create.list2cmdline(command)

    # Resolve standard stream arguments to handle values.
    std_handles_to_close = []
    try:
        std_input = _resolve_std_handle(stdin, default_null=False)
        std_output = _resolve_std_handle(stdout, default_null=False)
        std_error = _resolve_std_handle(stderr, default_null=False)

        # Track which handles we opened so we can close them after CreateProcess.
        if stdin == subprocess.DEVNULL:
            std_handles_to_close.append(std_input)
        if stdout == subprocess.DEVNULL:
            std_handles_to_close.append(std_output)
        if stderr == subprocess.DEVNULL:
            std_handles_to_close.append(std_error)

        # Build the full list of handles to inherit: the user's list plus the
        # standard handles (but only those that are non-zero).
        full_inherit_list = list(handles)
        for h in (std_input, std_output, std_error):
            if h and h not in full_inherit_list:
                full_inherit_list.append(h)

        # Make sure all the handles we are passing are actually inheritable.
        # We temporarily set the flag on handles that do not have it, then
        # restore the original state after CreateProcess.
        original_flags = {}
        for h in full_inherit_list:
            try:
                flags = _winapi.get_handle_flags(h)
                if not (flags & _winapi.HANDLE_FLAG_INHERIT):
                    original_flags[h] = flags
                    _winapi.set_handle_flags(h, _winapi.HANDLE_FLAG_INHERIT, _winapi.HANDLE_FLAG_INHERIT)
            except OSError as exc:
                # Clean up any flags we already changed before raising.
                for restore_h, restore_flags in original_flags.items():
                    try:
                        inherit_bit = restore_flags & _winapi.HANDLE_FLAG_INHERIT
                        _winapi.set_handle_flags(restore_h, _winapi.HANDLE_FLAG_INHERIT, inherit_bit)
                    except OSError:
                        pass
                raise WSpawnError(
                    "could not prepare handle %r for inheritance: %s" % (h, exc),
                    kind="os",
                    handle=h,
                ) from exc

        # Create the process.
        try:
            process_handle, pid = _create.create_process(
                command_line,
                full_inherit_list if full_inherit_list else None,
                std_input,
                std_output,
                std_error,
            )
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os") from exc
        finally:
            # Restore original inheritable flags.
            for h, flags in original_flags.items():
                try:
                    inherit_bit = flags & _winapi.HANDLE_FLAG_INHERIT
                    _winapi.set_handle_flags(h, _winapi.HANDLE_FLAG_INHERIT, inherit_bit)
                except OSError:
                    pass

    finally:
        # Close any handles we opened for DEVNULL.
        for h in std_handles_to_close:
            _winapi.close_handle(h)

    return SpawnedProcess(process_handle, pid, handles)

