from . import _winapi
from .errors import WSpawnError


def handle_kind(handle):
    """Return ``"file"``, ``"pipe"``, ``"console"`` or ``"unknown"``.

    The handle is validated with ``GetHandleInformation`` first, so an invalid
    value is reported as an error rather than being folded into ``"unknown"``.
    Once the object is known to be a live handle, ``GetFileType`` decides the
    bucket; anything the file API does not recognise (an event, a mutex, a
    process) is ``"unknown"``.
    """
    if not _winapi.is_windows():
        raise WSpawnError(
            "handle_kind needs the Win32 handle API", kind="unsupported", handle=handle
        )

    number = _as_handle(handle)

    # Establish that this is a live handle before asking what sort it is.
    # GetFileType cannot tell "not a file object" from "not a handle", so the
    # validity question has to be settled separately.
    try:
        _winapi.get_handle_flags(number)
    except OSError as exc:
        raise WSpawnError(
            "not a usable object handle: %r" % (handle,),
            kind="os",
            handle=handle,
        ) from exc

    file_type, _error = _winapi.get_file_type(number)

    if file_type == _winapi.FILE_TYPE_DISK:
        return "file"
    if file_type == _winapi.FILE_TYPE_PIPE:
        return "pipe"
    if file_type == _winapi.FILE_TYPE_CHAR:
        # A character device is a console only if the console API claims it;
        # NUL and the printer ports land here too.
        if _winapi.is_console_handle(number):
            return "console"
        return "unknown"

    # FILE_TYPE_UNKNOWN on a handle we already proved valid: a kernel object
    # the file API has no opinion about.
    return "unknown"


def _as_handle(handle):
    """Coerce *handle* to the integer a Win32 call can take."""
    if isinstance(handle, bool):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )
    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )
    if number <= 0:
        raise WSpawnError(
            "not a usable object handle: %r" % (handle,), kind="os", handle=handle
        )
    return number

"""Inheritance flags for the objects the host hands to its helpers.

On Windows, "inheritable" is a property of the *kernel handle*, recorded in
the object's handle-table entry and read back with ``GetHandleInformation``.
It is not a property of a CRT file descriptor, so the flag has to be set with
``SetHandleInformation`` for an external observer to see any change.
"""

from . import _winapi
from .errors import WSpawnError

#: Win32 error codes that mean "this object will never accept the request".
_UNSUPPORTED_ERRORS = frozenset((
    _winapi.ERROR_INVALID_PARAMETER,
    _winapi.ERROR_NOT_SUPPORTED,
    _winapi.ERROR_CALL_NOT_IMPLEMENTED,
    _winapi.ERROR_INVALID_FUNCTION,
    _winapi.ERROR_ACCESS_DENIED,
))


def _as_handle(handle):
    """Coerce *handle* to the integer a Win32 call can take."""
    if isinstance(handle, bool):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )
    try:
        return int(handle)
    except (TypeError, ValueError):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )


def _require_windows(name):
    if not _winapi.is_windows():
        raise WSpawnError(
            "%s needs the Win32 handle API" % name, kind="unsupported"
        )


def _classify(exc, handle, action):
    """Turn an :class:`OSError` from a handle call into a ``WSpawnError``."""
    code = getattr(exc, "winerror", None)
    if code in _UNSUPPORTED_ERRORS:
        return WSpawnError(
            "handle does not support %s: %s" % (action, exc),
            kind="unsupported",
            handle=handle,
        )
    return WSpawnError(str(exc), kind="os", handle=handle)


def set_inheritable(handle, enabled=True):
    """Mark ``handle`` as transferable to child processes, or stop it being so.

    The change is applied with ``SetHandleInformation`` and then read back, so
    a silent no-op is reported as ``unsupported`` rather than being mistaken
    for success.
    """
    _require_windows("set_inheritable")
    number = _as_handle(handle)
    wanted = bool(enabled)

    try:
        _winapi.set_handle_flags(
            number,
            _winapi.HANDLE_FLAG_INHERIT,
            _winapi.HANDLE_FLAG_INHERIT if wanted else 0,
        )
    except OSError as exc:
        raise _classify(exc, handle, "changing its inheritable flag") from exc

    # Confirm the flag actually moved.  Some objects accept the call and keep
    # their old state; that is a failure to honour the request, not a success.
    try:
        flags = _winapi.get_handle_flags(number)
    except OSError as exc:
        raise _classify(exc, handle, "reporting its inheritable flag") from exc

    if bool(flags & _winapi.HANDLE_FLAG_INHERIT) != wanted:
        raise WSpawnError(
            "handle did not accept the inheritable flag change",
            kind="unsupported",
            handle=handle,
        )


def is_inheritable(handle):
    """Return ``True`` when ``handle`` is currently transferable.

    Reads the live handle-table entry, so the answer always agrees with what
    an independent ``GetHandleInformation`` call reports.
    """
    _require_windows("is_inheritable")
    number = _as_handle(handle)

    try:
        flags = _winapi.get_handle_flags(number)
    except OSError as exc:
        raise _classify(exc, handle, "reporting its inheritable flag") from exc

    return bool(flags & _winapi.HANDLE_FLAG_INHERIT)


def inheritable_handles():
    """Return every object in this process that is currently transferable.

    Windows does not publish the handle table, so the set is recovered by
    sweeping the handle values the kernel hands out (always a multiple of
    four) and keeping the ones whose ``HANDLE_FLAG_INHERIT`` bit is set.  The
    sweep stops once it has accounted for every handle the process is known
    to hold.
    """
    if not _winapi.is_windows():
        raise WSpawnError(
            "inheritable_handles needs the Win32 handle API", kind="unsupported"
        )

    try:
        live_total = _winapi.process_handle_count()
    except OSError:
        live_total = 0

    found = []
    seen = 0
    probe = _winapi.try_handle_flags
    inherit_bit = _winapi.HANDLE_FLAG_INHERIT

    for candidate in range(4, _SWEEP_LIMIT, 4):
        flags = probe(candidate)
        if flags is None:
            continue
        seen += 1
        if flags & inherit_bit:
            found.append(candidate)
        if live_total and seen >= live_total:
            break

    return found


