#: a process of this shape, so this covers the table many times over while
#: keeping the sweep to a few milliseconds.
_SWEEP_LIMIT = 0x10000

"""Starting helper processes with a handover of the caller's objects.

The handover is done with ``CreateProcessW`` and a
``PROC_THREAD_ATTRIBUTE_HANDLE_LIST``: the attribute list names exactly the
objects the helper may touch, and the kernel builds the child's handle table
from that list alone.  Every other inheritable object in this process stays
behind, and the listed objects keep the handle value the caller knows them by.
"""

import os
import subprocess

from . import _create, _winapi
from .errors import WSpawnError


class SpawnedProcess(object):
