    def __init__(self, process_handle, pid, inherit):
        self._handle = process_handle
        self.inherit = tuple(inherit)
        self.pid = pid
        self.returncode = None

    def wait(self, timeout=None):
        """Block until the helper exits and return its exit code.

        Raises :class:`subprocess.TimeoutExpired` if *timeout* seconds pass
        first, matching what callers already expect from the standard library.
