        if self.returncode is not None:
            return self.returncode

        if timeout is None:
            timeout_ms = _create.INFINITE
        else:
            timeout_ms = max(0, int(float(timeout) * 1000))

        if not _create.wait_process(self._handle, timeout_ms):
            raise subprocess.TimeoutExpired(cmd=self.pid, timeout=timeout)

        self.returncode = _create.exit_code(self._handle)
        return self.returncode

