        """Return the exit code if the helper has finished, else ``None``.

        The wait object decides whether the process is done; the exit code on
        its own cannot, because a helper is free to exit with ``STILL_ACTIVE``.
        """
        if self.returncode is not None:
            return self.returncode

        if _create.wait_process(self._handle, 0):
            self.returncode = _create.exit_code(self._handle)
        return self.returncode

    def terminate(self):
        """Stop the helper."""
        _create.terminate_process(self._handle, 1)

    def close(self):
        """Release the process handle."""
        if self._handle:
            _winapi.close_handle(self._handle)
            self._handle = None

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError(
            "argv must be a sequence of arguments, not a single string", kind="badarg"
        )
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError(
            "argv must be an iterable of paths: %s" % exc, kind="badarg"
        ) from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError(
            "inherit must be a sequence of handles, not a single handle", kind="badarg"
        )
    try:
        return tuple(int(item) for item in inherit)
    except (TypeError, ValueError) as exc:
        raise WSpawnError(
            "inherit must contain integer handles: %s" % exc, kind="badarg"
        ) from exc


def _resolve_std(value, name, opened):
    """Turn a standard-stream argument into a handle value for the child.

    ``None`` leaves the stream disconnected (``0``), so an unasked-for stream
    never smuggles the parent's console in.  ``subprocess.DEVNULL`` opens
    ``NUL``; the handle is recorded in *opened* so the caller can close it once
    the child owns its own copy.  An integer is taken as a raw Win32 handle, and
    anything with ``fileno()`` is translated through the CRT.
    """
    if value is None:
        return 0

    if isinstance(value, int) and not isinstance(value, bool):
        if value == subprocess.DEVNULL:
            try:
                handle = _winapi.open_null_device()
            except OSError as exc:
                raise WSpawnError(
                    "could not open the null device for %s: %s" % (name, exc), kind="os"
                ) from exc
            opened.append(handle)
            return handle
        if value < 0:
            raise WSpawnError(
                "%s=%r is not a handle; wspawn does not create pipes for the "
                "caller" % (name, value),
                kind="unsupported",
            )
        return value

    try:
        descriptor = value.fileno()
    except AttributeError as exc:
        raise WSpawnError(
            "%s must be a handle, DEVNULL, None or an object with fileno(), "
            "got %r" % (name, value),
            kind="badarg",
        ) from exc
    except (OSError, ValueError) as exc:
        raise WSpawnError(
            "could not take a descriptor from %s=%r: %s" % (name, value, exc),
            kind="badarg",
        ) from exc

    import msvcrt

    try:
        return msvcrt.get_osfhandle(descriptor)
    except OSError as exc:
        raise WSpawnError(
            "descriptor %r behind %s has no Win32 handle: %s" % (descriptor, name, exc),
            kind="os",
        ) from exc


def _handover_table(handles, std_handles):
    """Build the deduplicated list of objects the child may access."""
    table = []
    for handle in tuple(handles) + tuple(std_handles):
        if handle and handle not in table:
            table.append(handle)
    return table


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The child receives the objects in *inherit* plus whichever standard
    streams were named, and nothing else: other inheritable objects in this
    process are left out of the child's handle table.  Handles arrive in the
    child under the same numeric value they have here.

    Returns a :class:`SpawnedProcess`.
    """
    if not _winapi.is_windows():
        raise WSpawnError(
            "spawn needs Win32 process creation", kind="unsupported"
        )

    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)
    command_line = _create.list2cmdline(command)

    opened = []
    try:
        std_in = _resolve_std(stdin, "stdin", opened)
        std_out = _resolve_std(stdout, "stdout", opened)
        std_err = _resolve_std(stderr, "stderr", opened)

        table = _handover_table(handles, (std_in, std_out, std_err))

        # The handle list is only honoured for objects that are themselves
        # marked inheritable, so borrow the flag for the duration of the call
        # and hand it back afterwards.  Anything we had to change is recorded
        # with its original flags.
        borrowed = {}
        try:
            for handle in table:
                try:
                    flags = _winapi.get_handle_flags(handle)
                except OSError as exc:
                    raise WSpawnError(
                        "cannot hand over %r: %s" % (handle, exc),
                        kind="os",
                        handle=handle,
                    ) from exc
                if not flags & _winapi.HANDLE_FLAG_INHERIT:
                    try:
                        _winapi.set_handle_flags(
                            handle,
                            _winapi.HANDLE_FLAG_INHERIT,
                            _winapi.HANDLE_FLAG_INHERIT,
                        )
                    except OSError as exc:
                        raise WSpawnError(
                            "object %r cannot be made inheritable: %s" % (handle, exc),
                            kind="unsupported",
                            handle=handle,
                        ) from exc
                    borrowed[handle] = flags

            try:
                process_handle, pid = _create.create_process(
                    command_line, table, std_in, std_out, std_err
                )
            except OSError as exc:
                raise WSpawnError(str(exc), kind="os") from exc
        finally:
            for handle, flags in borrowed.items():
                try:
                    _winapi.set_handle_flags(
                        handle,
                        _winapi.HANDLE_FLAG_INHERIT,
                        flags & _winapi.HANDLE_FLAG_INHERIT,
                    )
                except OSError:
                    pass
    finally:
        # The child holds its own references now; ours would otherwise keep
        # the null device alive for the lifetime of the host.
        for handle in opened:
            _winapi.close_handle(handle)

    return SpawnedProcess(process_handle, pid, handles)
